364	   349	    function refundTickets(uint256[] calldata ticketIds) external override nonReentrant returns (uint256 amount) {
365	   350	        _requireStatus(Status.Refunding);
366	   351	        uint256 ticketQuantity = ticketIds.length;
367	   352	        if (ticketQuantity == 0 || ticketQuantity > RaffleConstants.MAX_REFUND_TICKET_BATCH_SIZE) {
368	   353	            revert InvalidTicketBatchSize(ticketQuantity, RaffleConstants.MAX_REFUND_TICKET_BATCH_SIZE);
369	   354	        }
370	   355	
371	   356	        uint256 aggregateEntries = 0;
372	   357	        for (uint256 index; index < ticketQuantity; ++index) {
373	   358	            uint256 ticketId = ticketIds[index];
374	   359	            address owner = ownerOf(ticketId);
375	   360	            if (msg.sender != owner) revert NotTicketOwner(ticketId, msg.sender, owner);
376	   361	
377	   362	            (uint128 firstEntry, uint128 lastEntry) = ticketRange(ticketId);
378	   363	            aggregateEntries += uint256(lastEntry) - uint256(firstEntry) + 1;
379	   364	            _burn(ticketId);
380	   365	        }
381	   366	
382	   367	        amount = aggregateEntries * ENTRY_PRICE;
383	   368	        remainingRefundLiability -= amount;
384	   369	        _transferQuote(msg.sender, amount);
385	   370	        uint256 liabilityAfter = remainingRefundLiability;
386	   371	        emit TicketsRefunded(msg.sender, ticketQuantity, aggregateEntries, amount, liabilityAfter);
