264	   249	        uint256 quotedFee = getVrfRequestPrice();
265	   250	        if (msg.value < quotedFee) revert InsufficientVrfFee(quotedFee, msg.value);
266	   251	
267	   252	        status = Status.Drawing;
268	   253	        drawRequestedAt = uint64(block.timestamp);
269	   254	        _requestInFlight = true;
270	   255	        bytes memory extraArgs = VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({ nativePayment: true }));
271	   256	        uint256 paidPrice;
272	   257	        (requestId, paidPrice) = requestRandomnessPayInNative(callbackGasLimit, requestConfirmations, 1, extraArgs);
273	   258	        if (paidPrice > msg.value) revert InsufficientVrfFee(paidPrice, msg.value);
274	   259	        vrfRequestId = requestId;
275	   260	        _requestInFlight = false;
276	   261	
277	   262	        uint256 excess = msg.value - paidPrice;
278	   263	        if (excess != 0) {
279	   264	            bool success;
280	   265	            address refundRecipient = msg.sender;
281	   266	            assembly ("memory-safe") {
282	   267	                success := call(gas(), refundRecipient, excess, 0, 0, 0, 0)
283	   268	            }
284	   269	            if (!success) revert NativeRefundFailed(msg.sender, excess);
285	   270	        }
286	   271	
287	   272	        emit DrawRequested(requestId, msg.sender, paidPrice, excess, drawRequestedAt, callbackDeadline());
288	   273	    }
